function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must be lists of the same length.';
  if (operations[0] !== 'Leaderboard' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with Leaderboard and no arguments.';
  if (operations.length - 1 > 1000) return 'At most 1000 calls after the constructor.';
  const isId = v => Number.isInteger(v) && v >= 1 && v <= 10000;
  const onBoard = new Set();
  for (let i = 1; i < operations.length; i++) {
    const call = args[i];
    if (!Array.isArray(call)) return 'Each call needs a list of arguments.';
    if (operations[i] === 'addScore') {
      if (call.length !== 2 || !isId(call[0])) return 'addScore needs a playerId from 1 to 10^4 and a score.';
      if (!Number.isInteger(call[1]) || call[1] < 1 || call[1] > 100) return 'score is an integer from 1 to 100.';
      onBoard.add(call[0]);
    } else if (operations[i] === 'top') {
      if (call.length !== 1 || !isId(call[0])) return 'top needs a K from 1 to 10^4.';
      if (call[0] > onBoard.size) return 'K cannot be larger than the number of players on the board.';
    } else if (operations[i] === 'reset') {
      if (call.length !== 1 || !isId(call[0])) return 'reset needs a playerId from 1 to 10^4.';
      if (!onBoard.has(call[0])) return 'reset is only called for a player who is on the board.';
      onBoard.delete(call[0]);
    } else return 'Only addScore, top and reset can follow the constructor.';
  }
  return null;
}

