class Leaderboard {
  constructor() {
    this.scores = new Map();
  }

  addScore(playerId, score) {
    const current = this.scores.has(playerId) ? this.scores.get(playerId) : 0;
    this.scores.set(playerId, current + score);
  }

  top(K) {
    const totals = [...this.scores.values()];
    totals.sort((a, b) => b - a);
    let sum = 0;
    for (let i = 0; i < K; i++) {
      sum += totals[i];
    }
    return sum;
  }

  reset(playerId) {
    this.scores.delete(playerId);
  }
}

