class Leaderboard {
  // A plain list of [id, total] rows; top picks the largest remaining row K times.
  constructor() {
    this.rows = [];
  }
  addScore(playerId, score) {
    const row = this.rows.find(r => r[0] === playerId);
    if (row) row[1] += score;
    else this.rows.push([playerId, score]);
  }
  top(K) {
    const used = new Array(this.rows.length).fill(false);
    let total = 0;
    for (let picked = 0; picked < K; picked++) {
      let bestIndex = -1;
      for (let j = 0; j < this.rows.length; j++) {
        if (!used[j] && (bestIndex === -1 || this.rows[j][1] > this.rows[bestIndex][1])) bestIndex = j;
      }
      used[bestIndex] = true;
      total += this.rows[bestIndex][1];
    }
    return total;
  }
  reset(playerId) {
    this.rows = this.rows.filter(r => r[0] !== playerId);
  }
}

