function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  // A pool of ids makes repeated players common; large pools also reach the extreme ids.
  const pool = large ? [1, 10000] : [];
  const poolSize = large ? 120 : 1 + pick(5);
  while (pool.length < poolSize) {
    const id = large ? 1 + pick(10000) : 1 + pick(6);
    if (!pool.includes(id)) pool.push(id);
  }
  const onBoard = new Set();
  const operations = ['Leaderboard'];
  const args = [[]];
  const calls = large ? 499 : 1 + pick(10);
  for (let c = 0; c < calls; c++) {
    const roll = rand();
    if (onBoard.size > 0 && roll < 0.25) {
      const r = rand();
      const K = r < 0.2 ? 1 : r < 0.4 ? onBoard.size : 1 + pick(onBoard.size);
      operations.push('top');
      args.push([K]);
    } else if (onBoard.size > 0 && roll < 0.35) {
      const present = [...onBoard];
      const id = present[pick(present.length)];
      onBoard.delete(id);
      operations.push('reset');
      args.push([id]);
    } else {
      const id = pool[pick(pool.length)];
      const score = rand() < 0.1 ? 100 : 1 + pick(large ? 100 : 10);
      onBoard.add(id);
      operations.push('addScore');
      args.push([id, score]);
    }
  }
  return [operations, args];
}
